using System;

class Convertible
{
    [Obsolete("To int")]
    public static implicit operator int(Convertible c)
    {
        return 0;
    }

    [Obsolete("To bool")]
    public static implicit operator bool(Convertible c)
    {
        return false;
    }
}


class Test
{
    static void Main()
    {
        Convertible c = new Convertible();
        if (c)
        {
            switch (c)
            {
                case 0:
                    int x = c + 1;
                    x = +c;
                    break;
            }
        }
    }
}

